import { getBlossomServers, } from './nostr'
import { KINDS } from './nip22'
import { signEvent } from './auth'

async function sha256Hex(buf) {
  const digest = await crypto.subtle.digest('SHA-256', buf)
  return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('')
}

export async function buildBlossomAuth(verb, hash, ttlSec = 600) {
  const exp = Math.floor(Date.now() / 1000) + ttlSec
  const tags = [['t', verb], ['expiration', String(exp)]]
  if (hash) tags.push(['x', hash])
  const ev = await signEvent({
    kind: KINDS.BLOSSOM_AUTH,
    created_at: Math.floor(Date.now() / 1000) - 2,
    tags,
    content: verb === 'upload' ? 'Upload de arquivo (BraSocial)' : `Blossom ${verb} (BraSocial)`,
  })
  return btoa(JSON.stringify(ev))
}

const MIME_EXT = {
  'image/png': 'png', 'image/jpeg': 'jpg', 'image/gif': 'gif', 'image/webp': 'webp',
  'video/mp4': 'mp4', 'video/webm': 'webm',
}

export function blobUrlFor(server, hash, mime) {
  const ext = MIME_EXT[mime]
  return `${server.replace(/\/$/, '')}/${hash}${ext ? '.' + ext : ''}`
}

/** Upload a file to the first Blossom server that works; returns {url, server, hash, size, mime} */
export async function uploadToBlossom(file, { servers: serversOverride, onProgress } = {}) {
  const servers = serversOverride ? serversOverride : getBlossomServers()
  const buf = await file.arrayBuffer()
  const hash = await sha256Hex(buf)
  const auth = await buildBlossomAuth('upload', hash)
  let lastErr = null
  for (const server of servers) {
    const base = server.replace(/\/$/, '')
    try {
      const res = await fetch(`${base}/upload`, {
        method: 'PUT',
        headers: {
          Authorization: `Nostr ${auth}`,
          'X-SHA-256': hash,
          'Content-Type': file.type || 'application/octet-stream',
        },
        body: buf,
        signal: AbortSignal.timeout(30000),
      })
      if (!res.ok) {
        lastErr = new Error(`${base}: HTTP ${res.status}`)
        continue
      }
      const json = await res.json()
      const url = json.url || blobUrlFor(base, hash, file.type)
      return { url, server: base, hash, size: file.size, mime: file.type, name: file.name }
    } catch (e) {
      lastErr = e
    }
  }
  throw new Error(lastErr?.message || 'Nenhum servidor Blossom disponível')
}

/** try to find a blob on any known server (dedup / mirror) */
export async function mirrorCheck(hash, servers) {
  for (const server of servers) {
    try {
      const res = await fetch(`${server.replace(/\/$/, '')}/${hash}`, { method: 'HEAD' })
      if (res.ok) {
        const ct = res.headers.get('content-type') || ''
        return `${server.replace(/\/$/, '')}/${hash}${MIME_EXT[ct] ? '.' + MIME_EXT[ct] : ''}`
      }
    } catch {}
  }
  return null
}
