const CACHE_KEY = 'brasocial.translations'
const cache = (() => {
  try { return JSON.parse(localStorage.getItem(CACHE_KEY)) || {} } catch { return {} }
})()

function saveCache() {
  try {
    const keys = Object.keys(cache)
    if (keys.length > 4000) keys.slice(0, 1000).forEach((k) => delete cache[k])
    localStorage.setItem(CACHE_KEY, JSON.stringify(cache))
  } catch {}
}

export function browserLang() {
  return (navigator.language || 'en').slice(0, 2).toLowerCase()
}

export function cachedTranslation(text, target) {
  const entry = cache[`${target}:${text}`]
  return entry || null
}

async function viaGtxDirect(text, src, target) {
  const url = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=${src || 'auto'}&tl=${target}&dt=t&dj=1&q=${encodeURIComponent(text)}`
  const res = await fetch(url, { signal: AbortSignal.timeout(10000) })
  if (!res.ok) throw new Error(`gtx ${res.status}`)
  const body = await res.json()
  const out = (body.sentences || []).map((s) => s.trans || '').join('')
  const detected = body.src || null
  return { text: out, detected }
}

async function viaGtx(text, src, target) {
  try {
    return await viaGtxDirect(text, src, target)
  } catch {
    // fallback: mesmo endpoint via CORS proxy (uso de IP diferente)
    const gtxUrl = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=${src || 'auto'}&tl=${target}&dt=t&dj=1&q=${encodeURIComponent(text)}`
    const url = `https://cors.io/?url=${encodeURIComponent(gtxUrl)}`
    const res = await fetch(url, { signal: AbortSignal.timeout(10000) })
    if (!res.ok) throw new Error(`gtx ${res.status}`)
    const data = await res.json()
    const body = typeof data.body === 'string' ? JSON.parse(data.body) : data.body
    const out = (body.sentences || []).map((s) => s.trans || '').join('')
    const detected = body.src || null
    return { text: out, detected }
  }
}

