const inflight = new Map()

export async function translateText(text, src, target) {
  target = target || browserLang()
  if (!text?.trim()) return { text, detected: null, cached: true }
  const key = `${target}:${text}`
  const entry = cache[key]
  if (entry) return { text: entry.text, detected: entry.detected, cached: true }
  if (inflight.has(key)) return inflight.get(key)
  const p = (async () => {
    try {
      const { text: out, detected } = await viaGtx(text, src || 'auto', target)
      cache[key] = { text: out, detected }
      saveCache()
      return { text: out, detected, cached: false }
    } catch {
      const { text: out2, detected } = await viaMymemory(text, src, target)
      cache[key] = { text: out2, detected }
      saveCache()
      return { text: out2, detected, cached: false }
    }
  })().finally(() => inflight.delete(key))
  inflight.set(key, p)
  return p
}

export function clearTranslationCache() {
  for (const k of Object.keys(cache)) delete cache[k]
  localStorage.removeItem(CACHE_KEY)
}

export function isSameLang(obj) {
  if (!obj?.detected) return false
  return String(obj.detected).slice(0, 2).toLowerCase() === browserLang()
}
