// Global client-side event store with indices for threads, likes, reposts and
// reactions. Every pool subscription pushes events here; components re-render
// on a batched version bump. Nothing here touches a backend - everything is a
// Nostr event retrieved from relays.

import { parentIdOf, communityFromTags, KINDS } from './nip22'

const events = new Map() // id -> event
const byParent = new Map() // parentKey (event id or community addr) -> Set(childId)
const replKey = new Map() // replaceable key -> id (kind 34550, 34555 dedupe)

const likes = new Map() // targetId -> Set<pubkey>
const reposts = new Map() // targetId -> Set<pubkey>
const deletions = new Map() // deletedId -> Set<pubkey>

const listeners = new Set()
let flushTimer = null
let version = 0
export function storeVersion() { return version }

function notify() {
  if (flushTimer) return
  flushTimer = setTimeout(() => {
    flushTimer = null
    version++
    listeners.forEach((fn) => { try { fn() } catch {} })
  }, 150)
}

export function subscribeStore(fn) {
  listeners.add(fn)
  return () => listeners.delete(fn)
}

const REPL_KINDS = new Set([0, 3, 34550, 34555, 10063])

export function addEvent(ev) {
  if (!ev?.id || !ev.kind) return
  if (ev.kind === KINDS.BLOSSOM_AUTH) return

  if (REPL_KINDS.has(ev.kind)) {
    const addr = ev.kind === 0 || ev.kind === 3
      ? `${ev.kind}:${ev.pubkey}`
      : `${ev.kind}:${ev.pubkey}:${ev.tags.find((t) => t[0] === 'd')?.[1] || ''}`
    const prev = replKey.get(addr)
    if (prev) {
      const old = events.get(prev)
      if (old && old.created_at >= ev.created_at) return notify()
      events.delete(prev)
    }
    replKey.set(addr, ev.id)
    events.set(ev.id, ev)
    notify()
    return
  }

  if (events.has(ev.id)) return notify()
  const valid = /^[\da-f]{64}$/.test(ev.id) && /^[\da-f]{128}$/.test(ev.sig || '')
  if (!valid) return

  events.set(ev.id, ev)
  if (ev.kind === KINDS.POST || ev.kind === KINDS.COMMENT) {
    const parentKey = parentIdOf(ev) || communityFromTags(ev.tags)
    if (parentKey) {
      if (!byParent.has(parentKey)) byParent.set(parentKey, new Set())
      byParent.get(parentKey).add(ev.id)
    }
    for (const t of ev.tags) {
      if (t[0] === 'e' && t[1]?.length === 64) chainOf(t[1], ev)
      else if (t[0] === 'a' && t[1]?.startsWith('34550:')) chainOf(t[1], ev)
    }
  }
  if (ev.kind === KINDS.LIKE) {
    for (const t of ev.tags) {
      const tid = t[0] === 'e' ? t[1] : t[0] === 'a' ? t[1] : null
      if (tid && (t[0] === 'e' ? t[1]?.length === 64 : t[1]?.startsWith?.('34550:'))) {
        if (!likes.has(tid)) likes.set(tid, new Set())
        likes.get(tid).add(ev.pubkey)
      }
    }
  }
  if (ev.kind === KINDS.REPOST || ev.kind === KINDS.GENERIC_REPOST) {
    for (const t of ev.tags) {
      const tid = t[1] && (t[0] === 'e' ? t[1] : t[0] === 'a' ? t[1] : null)
      if (tid) {
        if (!reposts.has(tid)) reposts.set(tid, new Set())
        reposts.get(tid).add(ev.pubkey)
      }
    }
  }
  if (ev.kind === KINDS.DELETE) {
    for (const t of ev.tags) {
      if (t[0] === 'e' && t[1]?.length === 64) {
        if (!deletions.has(t[1])) deletions.set(t[1], new Set())
        deletions.get(t[1]).add(ev.pubkey)
      }
    }
  }
  notify()
}
function chainOf(target, ev) {
  const mapKey = target
  const map = byParent.get(mapKey) || (() => { const s = new Set(); byParent.set(mapKey, s); return s })()
  map.add(ev.id)
}

export function getEvent(id) { return events.get(id) }
export function childrenOf(parentKey) { return byParent.get(parentKey) || new Set() }
export function allEvents(returnArray) { return [...events.values()] }

export function hasLike(target, pk) { return likes.get(target)?.has(pk) || false }
export function hasRepost(target, pk) { return reposts.get(target)?.has(pk) || false }
export function likesOf(target) { return likes.get(target)?.size || 0 }
export function repostsOf(target) { return reposts.get(target)?.size || 0 }
export function isDeleted(id, mypk) {
  const ds = deletions.get(id)
  return !!ds && ds.has(mypk)
}
export function counts(id) {
  return { likes: likes.get(id)?.size || 0, reposts: reposts.get(id)?.size || 0, comments: childrenOf(id).size }
}
export function replaceableLoc(kind, pubkey, d) {
  const addr = `${kind}:${pubkey}:${d || ''}`
  return events.get(replKey.get(addr))
}
export function stats() {
  return { events: events.size, threads: byParent.size, likes: [...likes.values()].reduce((a, s) => a + s.size, 0), reposts: [...reposts.values()].reduce((a, s) => a + s.size, 0) }
}
