import React, { useMemo } from 'react'
import { useApp } from './ctx'
import { PostCard } from './PostCard'
import { LoadSpinner } from './Thumb'
import { CommentNode, CommentReply, LikeIcon } from './Comments'
import { useThread, useStoreVersion } from '../lib/hooks'
import { KINDS, parseRefs } from '../lib/nip22'

/** parent event id = last `e` tag (our own comments always write parent last) */
function parentOf(c) {
  const es = c.tags.filter((t) => t[0] === 'e').map((t) => t[1])
  return es[es.length - 1] || null
}

export function ThreadPage({ id }) {
  const { nav, user } = useApp()
  const { rootEvent, comments, eose } = useThread(id)
  useStoreVersion()

  const ctx = useMemo(() => {
    if (!rootEvent) return null
    const refs = parseRefs(rootEvent)
    return {
      community: refs.community,
      root: refs.community ? null : { id: rootEvent.id, kind: rootEvent.kind, pubkey: rootEvent.pubkey },
    }
  }, [rootEvent])

  const tops = useMemo(
    () => comments.filter((c) => parentOf(c) === id),
    [comments, id]
  )
  const groups = useMemo(() => {
    const m = new Map()
    for (const c of comments) {
      const p = parentOf(c)
      if (!p) continue
      if (!m.has(p)) m.set(p, [])
      m.get(p).push(c)
    }
    return m
  }, [comments])

  return (
    <div className="thread-page">
      <button className="btn back" onClick={() => history.length > 1 ? history.back() : nav('/')}>← Voltar</button>
      {!rootEvent && !eose && <div className="loading-row"><LoadSpinner /> buscando no relay…</div>}
      {rootEvent && <PostCard event={rootEvent} context="thread" clickable={false} />}
      {rootEvent && user && (
        <CommentReply target={rootEvent} community={ctx?.community} root={ctx?.root} onDone={null} />
      )}
      {tops.map((c) => (
        <CommentNode key={c.id} comment={c} groups={groups} root={ctx?.root} community={ctx?.community} depth={0} />
      ))}
      {!rootEvent && eose && (
        <p className="muted empty">Post não encontrado nos relays conectados. Pode ter sido deletado.</p>
      )}
    </div>
  )
}
