// NIP-22 (kind 1111 comments) + NIP-72 (mod communities) helpers.
// Compatible tags with Amethyst and other NIP-22 / NIP-72 clients.

import { nip19 } from 'nostr-tools'

export const KINDS = {

  POST: 1,
  COMMENT: 1111,
  REPOST: 6,
  GENERIC_REPOST: 16,
  LIKE: 7,
  DELETE: 5,
  PROFILE: 0,
  CONTACTS: 3,
  COMMUNITY_DEF: 34550,
  PINNED_GROUPS: 34555,
  BLOSSOM_SERVERS: 10063,
  BLOSSOM_AUTH: 24242,
}

export function tag(t, arr) { for (const a of arr) if (a[0] === t) return a; return null }
export function tagVal(t, arr) { return tag(t, arr)?.[1] ?? null }

export function dOf(ev) { return tagVal('d', ev.tags) || '' }
export function addressOf(ev) { return `${ev.kind}:${ev.pubkey}:${dOf(ev)}` }

export function communityAddr(ev) {
  return `34550:${ev.pubkey}:${dOf(ev)}`
}

export function communityFromTags(tags) {
  const a = tag('A', tags) || tag('a', tags)
  if (!a || !a[1]?.startsWith('34550:')) return null
  return a[1]
}

export function hashtagsOf(content) {
  const set = new Set()
  for (const m of String(content).matchAll(/(?:^|\s)#([\p{L}\p{N}_]+)/gu)) set.add(m[1].toLowerCase())
  return [...set]
}

export function urlsOf(content) {
  const set = new Set()
  for (const m of String(content).matchAll(/https?:\/\/[^\s<>"')]+/gu)) set.add(m[0])
  return [...set]
}

function extraRelay(list) { return relays(list)[0] || undefined }
export function relays(list) { return (list || []).filter((r) => typeof r === 'string' && r.startsWith('wss')) }

/**
 * Tags for a new NIP-22 comment (kind 1111).
 *
 * @param {{root: object|null, parent: object|null}} refs root event of thread, direct parent
 * @param {string|null} communityAddrStr if replying inside a NIP-72 community
 */
export function buildCommentTags({ root, parent, community: communityAddrStr }) {
  const t = []
  const rs = []
  if (communityAddrStr) {
    const [kind, pk] = communityAddrStr.split(':')
    t.push(['A', communityAddrStr])
    t.push(['K', '34550'])
    t.push(['P', pk])
    if (!parent) {
      // brand new top-level post scoped to the community
      t.push(['a', communityAddrStr])
      t.push(['k', '34550'])
      t.push(['p', pk])
    } else {
      t.push(['e', parent.id])
      t.push(['p', parent.pubkey])
      t.push(['k', String(parent.kind)])
    }
  } else if (root) {
    const rootKind = String(root.kind)
    t.push(['E', root.id, rs[0]].filter(Boolean))
    t.push(['K', rootKind])
    t.push(['P', root.pubkey])
    if (!parent || parent.id === root.id) {
      t.push(['e', root.id, rs[1]].filter(Boolean))
      t.push(['p', root.pubkey])
      t.push(['k', rootKind])
    } else {
      t.push(['e', parent.id, rs[1]].filter(Boolean))
      t.push(['p', parent.pubkey])
      t.push(['k', String(parent.kind)])
    }
  } else if (parent) {
    t.push(['e', parent.id, rs[0]].filter(Boolean))
    t.push(['p', parent.pubkey])
    t.push(['k', String(parent.kind)])
  }
  return t
}

/** Reconstruct thread refs from a known kind 1111 event */
export function parseRefs(ev) {
  const out = { root: null, parent: null, community: null }
  const K = tagVal('K', ev.tags), E = tagVal('E', ev.tags), A = tagVal('A', ev.tags)
  const Pup = tagVal('P', ev.tags)
  if (A?.startsWith('34550:')) {
    out.community = A
    const k = tagVal('e', ev.tags)
    if (k) out.parent = { id: k, kind: parseInt(tagVal('k', ev.tags) || '1111'), pubkey: tagVal('p', ev.tags) }
  } else if (E) {
    out.root = { id: E, kind: parseInt(K || '1'), pubkey: Pup }
    const k = tagVal('e', ev.tags)
    if (k && k !== E) out.parent = { id: k, kind: parseInt(tagVal('k', ev.tags) || '1'), pubkey: tagVal('p', ev.tags) }
    else if (k) out.parent = { id: k, kind: parseInt(K || '1'), pubkey: tagVal('p', ev.tags) }
  } else {
    const k = tagVal('e', ev.tags)
    if (k) out.root = { id: k, kind: parseInt(tagVal('k', ev.tags) || '1'), pubkey: tagVal('p', ev.tags) }
  }
  return out
}

export function parentIdOf(ev) {
  const es = ev.tags.filter((t) => t[0] === 'e').map((t) => t[1])
  return es[es.length - 1] || null
}

export function subjectOf(ev) {
  return tagVal('subject', ev.tags) || tagVal('title', ev.tags) || ''
}

export function communityOfEvent(ev) {
  if (ev.kind === KINDS.COMMENT) {
    const r = parseRefs(ev)
    return r.community
  }
  return tagVal('a', ev.tags) || null
}

/** media (blossom urls) embedded via imeta tags (NIP-92 style) */
export function mediaOf(ev) {
  const medias = []
  for (const t of ev.tags) {
    if (t[0] !== 'imeta' && t[0] !== 'url') continue
    let url = null
    if (t[0] === 'url') {
      url = String(t[1] || '').match(/https?:\/\/\S+/)?.[0] || null
    } else {
      for (let i = 1; i < t.length; i++) {
        if (/^https?:\/\//.test(t[i])) url = url || t[i]
        else url = url || String(t[i]).match(/https?:\/\/\S+/)?.[0] || null
      }
    }
    if (url) medias.push(url)
  }
  return medias
}

/** Tags for a brand-new top-level NIP-22 post scoped to a NIP-72 community */
export function communityFormTags(addr) {
  const [kind, pk, d] = addr.split(':')
  return [
    ['A', addr], ['a', addr],
    ['P', pk], ['p', pk],
    ['K', kind], ['k', kind],
  ]
}

/** bech32 nostr: uri of an event (for quoting inside posts) */
export function nip19Uri(ev) {
  return nip19.neventEncode({ id: ev.id, author: ev.pubkey, kind: ev.kind, relays: relays(ev.tags).slice(0, 2) })
}
