import React, { useEffect, useMemo, useRef, useState } from 'react'
import { nip19 } from 'nostr-tools'
import { useApp } from './ctx'
import { uploadToBlossom } from '../lib/blossom'
import {
  KINDS, buildCommentTags, hashtagsOf, communityFormTags, nip19Uri,
} from '../lib/nip22'
import { getEvent } from '../lib/store'
import { Avatar } from './Thumb'

function short(pk) {
  try { return nip19.npubEncode(pk).slice(0, 10) + '…' } catch { return pk?.slice(0, 8) }
}

/**
 * Unified composer.
 * - Global post        -> kind 1
 * - Community post     -> kind 1111 scoped to community (NIP-72)
 * - Reply (to anything)-> kind 1111 (NIP-22), Amethyst compatible
 * - Quote              -> kind 1/1111 with nostr:nevent + q tag
 */
export function Composer({ communityAddr = null, quoteId = null, replyTo = null, onClose }) {
  const { user, api, toast, nav } = useApp()
  const [text, setText] = useState('')
  const [title, setTitle] = useState('')
  const [busy, setBusy] = useState(false)
  const [uploads, setUploads] = useState([])
  const [uploading, setUploading] = useState(false)
  const fileRef = useRef(null)
  const taRef = useRef(null)
  const quoted = useMemo(() => (quoteId ? getEvent(quoteId) : null), [quoteId])
  const target = replyTo?.ev || null

  useEffect(() => {
    taRef.current?.focus()
    if (quoted && !text) setText(``)
  }, [])

  const pickFiles = async (files) => {
    if (!files?.length) return
    setUploading(true)
    for (const f of files) {
      if (f.size > 25 * 1024 * 1024) { toast('Arquivo maior que 25MB', 'warn'); continue }
      try {
        const r = await uploadToBlossom(f)
        setUploads((u) => [...u, r])
        toast(`Enviado para ${new URL(r.url).host}`)
      } catch (e) { toast(`Falha no upload: ${e.message || e}`, 'error') }
    }
    setUploading(false)
  }

  const publish = async () => {
    if (!text.trim() && !uploads.length && !quoted) return toast('Escreva algo ou anexe uma imagem', 'warn')
    setBusy(true)
    try {
      let content = text.trim()
      const tags = []

      const target = replyTo?.ev
      if (target) {
        tags.push(...buildCommentTags({
          root: replyTo.root?.id && replyTo.root.id !== target.id ? replyTo.root : null,
          parent: target,
          community: replyTo.community,
        }))
      } else if (communityAddr) {
        tags.push(...communityFormTags(communityAddr))
      }
      if (title.trim()) tags.push(['subject', title.trim()])
      for (const h of hashtagsOf(content)) tags.push(['t', h])
      for (const up of uploads) {
        content += (content ? '\n' : '') + up.url
        tags.push(['imeta', `url ${up.url}`, `mime ${up.mime || 'application/octet-stream'}`])
      }
      if (quoted) {
        content += (content ? '\n' : '') + `nostr:${nip19Uri(quoted)}`
        tags.push(['q', quoted.id, '', quoted.pubkey])
      }

      const kind = target || communityAddr ? KINDS.COMMENT : KINDS.POST
      if (/nsec1[a-z0-9]{20,}/.test(content)) {
        setBusy(false)
        return toast('Isso parece uma chave privada (nsec). NUNCA publique isso!', 'error')
      }
      const ev = await api.signEvent({ kind, content, tags })
      const res = await api.publishEvent(ev)
      toast(res.ok.length ? `Publicado em ${res.ok.length} relays` : 'Nenhum relay aceitou a publicação', res.ok.length ? 'ok' : 'error')
      if (res.ok.length) {
        setText(''); setTitle(''); setUploads([])
        if (ev.id) {}
        onClose?.(ev)
      }
    } catch (e) { toast(String(e.message || e), 'error') }
    setBusy(false)
  }

  if (!user) {
    return (
      <div className="composer-card">
        <p className="muted">Conecte uma conta (nsec, NIP-07 ou criar chaves) para publicar.</p>
        <button className="btn primary" onClick={() => nav('/login')}>Conectar</button>
      </div>
    )
  }

  return (
    <div className="composer-card">
      {communityAddr && <div className="composer-context">postando em: c/{communityAddr.split(':')[2]}</div>}
      {target && (
        <div className="quote-preview small muted">
          respondendo a <b>{short(target.pubkey)}</b> — thread {replyTo.root ? 'raiz' : 'direta'}
        </div>
      )}
      {quoted && (
        <div className="quote-preview">
          <span className="tiny">Citação de <b>{short(quoted.pubkey)}</b></span>
          <div className="small muted">{(quoted.content || '').slice(0, 200) || '(sem texto)'}</div>
        </div>
      )}
      {communityAddr && (
        <input
          className="composer-title" placeholder="Título (opcional, estilo Reddit)"
          value={title} onChange={(e) => setTitle(e.target.value)} maxLength={180}
        />
      )}
      <div className="composer-row">
        <Avatar pk={user.pubkey} size={36} />
        <textarea
          ref={taRef}
          className="composer-text"
          rows={target ? 3 : 4}
          placeholder={target ? 'Escreva seu comentário…' : communityAddr ? 'Poste no grupo…' : 'O que está acontecendo? Compartilhe com o Brasil!'}
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => { if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') { e.preventDefault(); publish() } }}
          maxLength={5000}
        />
      </div>
      {uploads.length > 0 && (
        <div className="composer-uploads">
          {uploads.map((u) => (
            <a key={u.url} href={u.url} target="_blank" rel="noreferrer" className="upload-chip">
              {u.mime?.startsWith('image/') ? <img src={u.url} alt={u.name} /> : <span>📄 {u.name}</span>}
              <button onClick={(e) => { e.preventDefault(); setUploads((l) => l.filter((x) => x.url !== u.url)) }}>×</button>
            </a>
          ))}
        </div>
      )}
      <div className="composer-actions">
        <input ref={fileRef} type="file" accept="image/*,video/*" multiple hidden onChange={(e) => pickFiles(e.target.files)} />
        <button className="btn ghost" disabled={uploading} onClick={() => fileRef.current?.click()}>
          {uploading ? 'subindo…' : '🖼 Imagem (Blossom)'}
        </button>
        <span className="flex1" />
        {onClose && <button className="btn ghost" onClick={() => onClose?.()}>Cancelar</button>}
        <button className="btn primary" disabled={busy || uploading} onClick={publish}>
          {busy ? 'publicando…' : 'Publicar'}
        </button>
      </div>
    </div>
  )
}