import React, { useState } from 'react'
import { CtxProvider, useApp } from './ctx'
import { FeedPage } from './Feed'
import { GroupsPage, GroupPage, addrName } from './Groups'
import { ProfilePage } from './Profile'
import { ThreadPage } from './ThreadPage'
import { SettingsPage } from './Settings'
import { Composer } from './Composer'
import { LoginModal } from './Login'
import { DmInbox, DmThread } from './Dm'
import { Avatar } from './Thumb'
import { nip19 } from 'nostr-tools'
import { stats } from '../lib/store'
import { useStoreVersion } from '../lib/hooks'
import { browserLang } from '../lib/translate'
import { getRelays, pool } from '../lib/nostr'

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props)
    this.state = { err: null }
  }
  static getDerivedStateFromError(err) { return { err } }
  componentDidCatch(err, info) { console.error('BraSocial render error:', err, info) }
  render() {
    if (this.state.err) {
      return (
        <div className="empty card" style={{ padding: 24 }}>
          <h3>Ops, erro ao renderizar esta parte 🤔</h3>
          <pre className="tiny muted" style={{ whiteSpace: 'pre-wrap' }}>{String(this.state.err?.message || this.state.err)}</pre>
          <button className="btn primary" onClick={() => location.reload()}>Recarregar o app</button>
          <button className="btn ghost" onClick={() => this.setState({ err: null })}>Tentar novamente</button>
        </div>
      )
    }
    return this.props.children
  }
}

export default function App() {
  return (
    <CtxProvider>
      <ErrorBoundary>
        <Shell />
      </ErrorBoundary>
    </CtxProvider>
  )
}

function Shell() {
  const { route, user, nav, settings, setSetting, toast } = useApp()
  useStoreVersion()
  const [loginOpen, setLoginOpen] = useState(false)
  const [composerOpen, setComposerOpen] = useState(false)
  const routeName = route.name

  return (
    <div className="app">
      <header className="topbar">
        <div className="topbar-inner">
          <button className="brand" onClick={() => nav('/')}>
            <span className="brand-dot">Br</span> BraSocial
          </button>
          <nav className="topnav hide-mobile">
            <button className={routeName === 'home' ? 'on' : ''} onClick={() => nav('/')}>Feed</button>
            <button className={routeName === 'groups' ? 'on' : ''} onClick={() => nav('/groups')}>Grupos</button>
            <button className={routeName === 'settings' ? 'on' : ''} onClick={() => nav('/settings')}>Config</button>
          </nav>
          <span className="flex1" />
          <button
            className={`btn ghost tiny ${settings.autoTranslate ? 'on' : ''}`}
            title="Tradução automática (idioma do navegador)"
            onClick={() => { setSetting('autoTranslate', !settings.autoTranslate); }}
          >
            {settings.autoTranslate ? `🌐 ${browserLang().toUpperCase()}` : '🌐 off'}
          </button>
          {user ? (
            <button className="btn primary tiny" onClick={() => setComposerOpen(true)}>+ Novo post</button>
          ) : null}
          {user ? (
            <button className="avatar-btn" onClick={() => nav(`/u/${nip19.npubEncode(user.pubkey)}`)}>
              <Avatar pk={user.pubkey} size={32} />
            </button>
          ) : (
            <button className="btn primary" onClick={() => setLoginOpen(true)}>Conectar</button>
          )}
        </div>
      </header>

      <div className="page">
        {routeName !== 't' && <Sidebar />}
        <main className="main">
          <ErrorBoundary key={`${route.name}:${route.params.join('/')}:${route.nonce || 0}`}>
            <Route route={route} />
          </ErrorBoundary>
        </main>
        {!['t', 'settings'].includes(routeName) && <RightRail />}
      </div>

      {(loginOpen || routeName === 'login') && <LoginModal onClose={() => setLoginOpen(false)} />}
      {composerOpen && <ComposerModal onClose={() => setComposerOpen(false)} />}
      {mobileBar(user, nav, setLoginOpen, setComposerOpen)}
      <Footer />
    </div>
  )
}

function ComposerModal({ onClose }) {
  const { route } = useApp()
  const quoteId = route.query?.q || null
  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal wide card" onClick={(e) => e.stopPropagation()}>
        <h3>{route.query?.q ? 'Citar this post' : 'Novo post'}</h3>
        <Composer quoteId={quoteId} onClose={onClose} />
      </div>
    </div>
  )
}

function Route({ route }) {
  const { nav } = useApp()
  // hash params arrive percent-encoded (e.g. %C2%A0) — decode, tolerating invalid input
  const dec = (s) => { try { return decodeURIComponent(s) } catch { return s } }
  switch (route.name) {
    case 'home': return <FeedPage />
    case 'tag': return <FeedPage />
    case 'groups': return <GroupsPage />
    case 'g': {
      // params[0] is the full addr "34550:<pk>:<d>" (d may itself contain ':')
      const segs = dec(route.params[0] || '').split(':')
      const kind = segs[0], pk = segs[1], d = segs.slice(2).join(':')
      if (kind !== '34550' || !pk || segs.length < 3) return <p className="muted empty">Grupo inválido.</p>
      return <GroupPage pk={pk} d={d} />
    }
    case 't': return <ThreadPage id={dec(route.params[0])} />
    case 'u': return <ProfilePage npubOrHex={dec(route.params[0])} />
    case 'dm': return route.params.length ? <DmThread npubOrHex={dec(route.params[0])} /> : <DmInbox />
    case 'settings': return <SettingsPage />
    case 'compose': return (
      <div>
        <button className="btn back" onClick={() => nav('/')}>←</button>
        <h3>Novo post</h3>
        <Composer quoteId={route.query?.q || null} onClose={() => nav('/')} />
      </div>
    )
    case 'login': return <div className="empty muted">Escolha uma opção…</div>
    default: return (
      <div className="empty muted">
        Página não encontrada. <button className="btn primary" onClick={() => nav('/')}>Início</button>
      </div>
    )
  }
}

function Sidebar() {
  const { route, nav, user, joined } = useApp()
  useStoreVersion()
  return (
    <aside className="sidebar hide-mobile">
      <SidebarLink icon="🏠" label="Feed" active={route.name === 'home'} onClick={() => nav('/')} />
      <SidebarLink icon="👥" label="Grupos" active={route.name === 'groups' || route.name === 'g'} onClick={() => nav('/groups')} />
      <SidebarLink icon="⚙️" label="Configurações" active={route.name === 'settings'} onClick={() => nav('/settings')} />
      {user && (
        <SidebarLink icon="✉️" label="Mensagens" active={route.name === 'dm'} onClick={() => nav('/dm')} />
      )}
      {user && (
        <>
          <SidebarLink icon="👤" label="Meu perfil" onClick={() => nav(`/u/${nip19.npubEncode(user.pubkey)}`)} />
          <div className="sidebar-head">Meus grupos</div>
          {joined.map((a) => (
            <button key={a} className="chip" onClick={() => nav(`/g/${a}`)}>c/{addrName(a)}</button>
          ))}
        </>
      )}
    </aside>
  )
}

function SidebarLink({ icon, label, active, onClick }) {
  return (
    <button className={`sidebar-link ${active ? 'active' : ''}`} onClick={onClick}>
      <span className="icon">{icon}</span> {label}
    </button>
  )
}

function RightRail() {
  useStoreVersion()
  const st = stats()
  return (
    <aside className="rail hide-mobile">
      <div className="card rail-card">
        <h4>🇧🇷 BraSocial</h4>
        <p className="tiny muted">rede social sem servidor central, P2P sobre o protocolo Nostr.<br />feed + grupos estilo Telegram + comentários aninhados.</p>
      </div>
      <div className="card rail-card">
        <h4>Estado local</h4>
        <div className="tiny">{st.events} eventos · {st.threads} threads</div>
        <div className="tiny">{getRelays().length} relays ativos</div>
      </div>
    </aside>
  )
}

function mobileBar(user, nav, openLogin, openComposer) {
  if (!window.matchMedia?.('(max-width: 760px)').matches) return null
  return (
    <nav className="mobile-bar">
      <button onClick={() => nav('/')}>🏠</button>
      <button onClick={() => nav('/groups')}>👥</button>
      {user && <button onClick={() => nav('/dm')}>✉️</button>}
      {user
        ? <button className="fab" onClick={openComposer}>+</button>
        : <button className="fab" onClick={openLogin}>🔑</button>}
      <button onClick={() => nav('/settings')}>⚙️</button>
      {user && <Avatar pk={user.pubkey} size={30} onClick={() => nav(`/u/${nip19.npubEncode(user.pubkey)}`)} />}
    </nav>
  )
}

function Footer() {
  return (
    <footer className="footer tiny muted">
      BraSocial · 100% front-end, sem backend, sobre Nostr (NIP-01, NIP-22, NIP-72, NIP-B) · compatível com Amethyst
    </footer>
  )
}
