import React, { useEffect, useMemo, useState } from 'react'
import { nip19 as nip19lib } from 'nostr-tools'
import { useApp } from './ctx'
import { PostCard } from './PostCard'
import { Avatar, LoadSpinner } from './Thumb'
import { useProfile, useContacts, useSub, useSortedEvents } from '../lib/hooks'
import { KINDS } from '../lib/nip22'
import { uploadToBlossom } from '../lib/blossom'
import { verifyNip05, dedupeRecent } from '../lib/util'

export function ProfilePage({ npubOrHex }) {
  const { user, nav, api, toast } = useApp()
  const pk = useMemo(() => {
    if (npubOrHex?.startsWith('npub') || npubOrHex?.startsWith('nprofile')) {
      try { return nip19lib.decode(npubOrHex).data } catch { return npubOrHex }
    }
    return npubOrHex
  }, [npubOrHex])
  const prof = useProfile(pk)
  const isMe = user?.pubkey === pk
  const following = useContacts(pk)
  const myContacts = useContacts(user?.pubkey)
  const [editing, setEditing] = useState(false)
  const [iFollow, setIFollow] = useState(false)
  useEffect(() => { setIFollow(!!(myContacts && myContacts.includes(pk))) }, [myContacts, pk])
  const { ids } = useSub(pk ? [
    { kinds: [KINDS.POST], authors: [pk], limit: 200 },
    { kinds: [KINDS.COMMENT], authors: [pk], limit: 200 },
  ] : null, { enabled: !!pk, ceil: 250 })
  const evs = useSortedEvents(ids)
  const posts = useMemo(() => dedupeRecent(evs).filter((ev) => ev.kind === KINDS.POST || (ev.kind === KINDS.COMMENT && !ev.tags.some((t) => t[0] === 'e'))), [evs])
  if (!pk || !pk.match?.(/^[0-9a-fA-F]{64}$/)) {
    return <p className="muted empty">Perfil inválido: {String(npubOrHex).slice(0, 40)}</p>
  }

  return (
    <div className="profile-page">
      <div className="profile-card card">
        <div className="profile-banner" />
        <Avatar pk={pk} size={90} picture={prof?.picture} />
        <h2>{prof?.display_name || prof?.name || 'perfil'}</h2>
        <div className="muted small">@{prof?.name || pk?.slice(0, 12)}</div>
        {prof?.nip05 && <Nip05 pk={pk} nip05={prof.nip05} />}
        {prof?.website && <a href={prof.website} target="_blank" rel="noreferrer" className="ext-link">{prof.website}</a>}
        <p className="prewrap">{prof?.about || ''}</p>
        <div className="profile-meta">
          {following && <span className="small">{following.length} seguindo</span>}
        </div>
        <div className="row gap">
          {isMe ? (
            <button className="btn primary" onClick={() => setEditing(true)}>Editar perfil</button>
          ) : user ? (
            <button className="btn primary" onClick={() => toggleFollow(iFollow, user, api, toast, myContacts, pk)}>
              {iFollow ? '✓ Seguindo' : '+ Seguir'}
            </button>
          ) : (
            <button className="btn primary" onClick={() => nav('/login')}>Conectar para seguir</button>
          )}
          {user && !isMe && (
            <button className="btn ghost" onClick={() => nav(`/dm/${nip19lib.npubEncode(pk)}`)}>✉ DM</button>
          )}
          <button className="btn ghost" onClick={() => nav('/settings')}>Configurações</button>
        </div>
      </div>
      <h3 className="section-title">Publicações</h3>
      {posts.map((ev) => <PostCard key={ev.id} event={ev} context="profile" />)}
      {evs.length === 0 && <div className="muted empty"><LoadSpinner /> buscando posts do perfil…</div>}
      {editing && <EditProfileModal onClose={() => setEditing(false)} prof={prof} />}
    </div>
  )
}

async function toggleFollow(isF, user, api, toast, myContacts, pk) {
  try {
    const tags = []
    const seen = new Set([pk])
    for (const t of myContacts || []) {
      if (t[0] !== 'p' || t[1]?.length !== 64) continue
      if (isF && t[1] === pk) continue
      if (!seen.has(t[1])) { seen.add(t[1]); tags.push(['p', t[1]]) }
    }
    if (!isF) tags.push(['p', pk])
    const ev = await api.signEvent({ kind: KINDS.CONTACTS, tags, content: '' })
    await api.publishEvent(ev)
    toast(isF ? 'Deixou de seguir' : 'Seguindo!', 'ok')
  } catch (e) { toast(String(e), 'error') }
}

function decodeAny(s) { return nip19lib.decode(s) }

function Nip05({ pk, nip05 }) {
  const [ok, setOk] = useState(false)
  useEffect(() => { verifyNip05(nip05, pk).then(setOk).catch(() => {}) }, [nip05, pk])
  return (
    <div className={`nip05-line ${ok ? 'ok' : ''}`}>
      {ok ? `✓ ${nip05} verificado` : nip05}
    </div>
  )
}

export function EditProfileModal({ onClose, prof }) {
  const { user, api, toast } = useApp()
  const [f, setF] = useState({
    display_name: prof?.display_name || '',
    name: prof?.name || '',
    about: prof?.about || '',
    picture: prof?.picture || '',
    website: prof?.website || '',
    nip05: prof?.nip05 || '',
    lud16: prof?.lud16 || '',
  })
  const [busy, setBusy] = useState(false)
  const fileRef = React.useRef(null)
  const setField = (k) => (e) => setF((s) => ({ ...s, [k]: e.target.value }))
  const uploadPicture = async (file) => {
    try {
      const r = await uploadToBlossom(file)
      setF((s) => ({ ...s, picture: r.url }))
      toast('Foto enviada (Blossom)')
    } catch (e) { toast('Falha no upload: ' + (e.message || e), 'error') }
  }
  const save = async () => {
    setBusy(true)
    try {
      const meta = { picture: '', ...prof, ...f }
      delete meta.event
      delete meta.pubkey
      const ev = await api.signEvent({ kind: KINDS.PROFILE, content: JSON.stringify(meta), tags: [] })
      const res = await api.publishEvent(ev)
      if (res.ok.length) toast('Perfil atualizado!', 'ok'); else toast('Nenhum relay aceitou', 'error')
      onClose?.()
    } catch (e) { toast(String(e), 'error') }
    setBusy(false)
  }
  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal card" onClick={(e) => e.stopPropagation()}>
        <h3>Editar perfil</h3>
        <div className="row">
          {f.picture && <img src={f.picture} alt="" style={{ width: 64, height: 64, borderRadius: '50%', objectFit: 'cover' }} />}
          <input ref={fileRef} type="file" accept="image/*" hidden onChange={(e) => e.target.files[0] && uploadPicture(e.target.files[0])} />
          <button className="btn ghost" onClick={() => fileRef.current?.click()}>🖼 Foto (Blossom)</button>
        </div>
        <label className="field">Nome de exibição<input value={f.display_name} onChange={setField('display_name')} maxLength={80} /></label>
        <label className="field">Nome de usuário<input value={f.name} onChange={setField('name')} maxLength={50} placeholder="brazuca" /></label>
        <label className="field">Descrição<textarea value={f.about} onChange={setField('about')} rows={3} maxLength={600} /></label>
        <label className="field">NIP-05 verificação<input value={f.nip05} onChange={setField('nip05')} placeholder="voce@dominio.com.br" /></label>
        <label className="field">Website<input value={f.website} onChange={setField('website')} placeholder="https://meusite.com.br" /></label>
        <label className="field">Lightning (lud16)<input value={f.lud16} onChange={setField('lud16')} placeholder="voce@wallet.com.br" /></label>
        <div className="row end gap">
          <button className="btn ghost" onClick={onClose}>Cancelar</button>
          <button className="btn primary" disabled={busy} onClick={save}>{busy ? 'salvando…' : 'Salvar'}</button>
        </div>
      </div>
    </div>
  )
}
